const p = window.portfolio;
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe = url => /^(https?:\/\/|mailto:|(?:images|files)\/)/i.test(url||'') ? esc(url) : '';
const routes = [['index.html','About'],['education.html','Education'],['projects.html','Projects'],['publications.html','Publications'],['certifications.html','Certifications'],['awards.html','Awards']];
const page = location.pathname.split('/').pop() || 'index.html';
const title = routes.find(r=>r[0]===page)?.[1] || 'About';
document.title = `${title} · ${p.name} · Academic portfolio`;
const icon = '<svg viewBox="0 0 40 40" aria-hidden="true"><rect x="5" y="5" width="30" height="30" rx="1"/><circle cx="15" cy="15" r="3"/><path d="m6 29 9-8 6 5 7-11 7 14"/></svg>';
function picture(src,label,extra=''){return safe(src)?`<img class="${extra}" src="${safe(src)}" alt="${esc(label)}">`:`<div class="placeholder ${extra}">${icon}<strong>${esc(label)}</strong><small>Space for your image</small></div>`;}
function link(url,label,cls='text-link'){return safe(url)?`<a class="${cls}" href="${safe(url)}">${esc(label)}</a>`:'';}
function heading(no,name,description){return `<header class="page-heading"><div class="eyebrow">Academic portfolio / ${no}</div><h1>${name}</h1><p>${description}</p></header>`;}
function project(item,i){return `<article>${picture(item.image,'Project image '+(i+1),'project-image')}<div class="project-info"><div class="meta"><span>${esc(item.category)}</span><span>${esc(item.year)}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><details class="project-detail"><summary>Project details</summary><p>${esc(item.detail)}</p>${link(item.url,'View project')}</details></div></article>`;}
function publication(item,i){return `<article class="publication"><div class="publication-index">${String(i+1).padStart(2,'0')}</div><div><span class="badge">${esc(item.type)}</span><h3>${esc(item.title)}</h3><p>${esc(item.authors)}</p><p class="venue">${esc(item.venue)} · ${esc(item.year)}</p><details><summary>Read abstract</summary><p>${esc(item.abstract)}</p></details>${item.url?`<p style="margin-top:16px">${link(item.url,'Read publication')}</p>`:''}</div></article>`;}
function contact(){return `<section class="contact-panel" id="contact"><div><span class="contact-label">Get in touch</span><h2 style="margin-top:12px">Let’s connect.</h2><p>[Add a short note about research collaborations, academic opportunities, or other enquiries you welcome.]</p></div><div><span class="contact-label">Email</span><div class="contact-value">${p.email?`<a href="mailto:${esc(p.email)}">${esc(p.email)}</a>`:'[Your academic email address]'}</div><span class="contact-label">Based at</span><p>${esc(p.university)}<br>${esc(p.location)}</p><div class="footer-nav">${link(p.scholar,'Google Scholar')}${link(p.orcid,'ORCID')}${link(p.github,'GitHub')}</div></div></section>`;}
let body = '';
if(title==='About') body=`<section class="hero"><div><div class="eyebrow">Research · Inquiry · Discovery</div><h1>${esc(p.name)}</h1><p class="role">${esc(p.role)}</p><div class="affiliation">${esc(p.department)}<br>${esc(p.university)}</div><p class="intro">${esc(p.introduction)}</p><div class="actions"><a class="button primary" href="projects.html">Explore my research</a>${p.cv?link(p.cv,'Curriculum vitae','button'):'<a class="button" href="#contact">Get in touch</a>'}</div></div><div><div class="portrait-wrap">${picture(p.portrait,'Your portrait','portrait')}</div><div class="portrait-caption"><span>${esc(p.location)}</span><span>Academic portfolio</span></div></div></section><div class="interest-strip"><span>Research interests</span><div class="tags">${p.interests.map(i=>`<span class="tag">${esc(i)}</span>`).join('')}</div></div><section class="section split"><div><span class="number">01 / BACKGROUND</span><h2 style="margin-top:12px">A little about me.</h2></div><div class="prose"><p>${esc(p.biography)}</p><p>${esc(p.approach)}</p></div></section><section class="section"><div class="section-heading"><div><span class="number">02 / RESEARCH</span><h2>Selected projects</h2></div><a class="text-link" href="projects.html">All projects</a></div><div class="project-grid">${p.projects.slice(0,2).map(project).join('')}</div></section><section class="section"><div class="section-heading"><div><span class="number">03 / SCHOLARSHIP</span><h2>Selected publications</h2></div><a class="text-link" href="publications.html">All publications</a></div>${p.publications.slice(0,2).map(publication).join('')}</section>${contact()}`;
if(title==='Education') body=heading('01','Education','Academic training, research foundations, and the path to my current work.')+`<section class="timeline">${p.education.map(e=>`<article class="timeline-row"><div class="timeline-date">${esc(e.period)}</div><div><h3>${esc(e.degree)}</h3><p class="institution">${esc(e.institution)}</p><p>${esc(e.detail)}</p></div></article>`).join('')}</section>`+contact();
if(title==='Projects') body=heading('02','Research & projects','A closer look at the questions, methods, and outcomes behind my work.')+`<section class="project-grid section">${p.projects.map(project).join('')}</section>`+contact();
if(title==='Publications') body=heading('03','Publications','Journal articles, conference contributions, and work in progress.')+`<section class="section" style="padding-top:10px">${p.publications.map(publication).join('')}</section>`+contact();
if(title==='Certifications') body=heading('04','Certifications','Specialist training and continued professional development.')+`<section class="detail-grid">${p.certifications.map(c=>`<article class="credential">${picture(c.image,'Certificate image','project-image')}<div class="credential-body"><div class="meta"><span>${esc(c.year)}</span></div><h3>${esc(c.title)}</h3><p class="institution">${esc(c.issuer)}</p><p>${esc(c.detail)}</p>${link(c.url,'View credential')}</div></article>`).join('')}</section>`+contact();
if(title==='Awards') body=heading('05','Awards & recognition','Academic distinctions, scholarships, and recognition of my work.')+`<section class="timeline">${p.awards.map(a=>`<article class="timeline-row"><div class="timeline-date">${esc(a.year)}</div><div><h3>${esc(a.title)}</h3><p class="institution">${esc(a.issuer)}</p><p>${esc(a.detail)}</p></div></article>`).join('')}</section>`+contact();
document.getElementById('app').innerHTML=`<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="index.html" aria-label="Portfolio home"><span class="monogram">${esc(p.initials)}</span><div><div class="brand-name">${esc(p.name)}</div><div class="brand-sub">Academic portfolio</div></div></a><button class="menu-toggle" type="button" aria-controls="navigation" aria-expanded="false">Menu</button><nav class="nav" id="navigation" aria-label="Main navigation">${routes.map(([url,label])=>`<a href="${url}" ${title===label?'aria-current="page"':''}>${label}</a>`).join('')}</nav></div></header><main class="shell" id="main">${body}</main><footer class="site-footer"><div class="shell footer-inner"><span>© ${new Date().getFullYear()} ${esc(p.name)}. Academic portfolio.</span><div class="footer-nav"><a href="index.html">About</a><a href="index.html#contact">Contact</a><a href="#main">Back to top</a></div></div></footer>`;
document.querySelector('.menu-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));document.querySelector('.nav').classList.toggle('open',open);});
